from itertools import product

def count_zeros(n):
    return str(n).count('0')

def has_no_zeros(n):
    return '0' not in str(n)

def check_max_a(L):
    # Try all Q with k digits, where k is from L down to 1.
    # For each Q, we want to know if there exists N such that
    # the interval [N*Q, N*(Q+1)-1] contains an M with no zeros and L digits.
    # This is still too many Qs.
    # But we only care about Q with many zeros.
    # Let's try Q that are just d * 10**(k-1).
    max_a = 0
    for k in range(1, L + 1):
        for d in range(1, 10):
            Q = d * (10**(k-1))
            # Search for N
            # N*Q < 10**L and N*(Q+1)-1 >= 10**(L-1)
            n_min = (10**(L-1) + 1) // (Q + 1)
            n_max = (10**L - 1) // Q
            for N in range(int(n_min), int(n_max) + 1):
                # Check if [N*Q, N*(Q+1)-1] has an M with no zeros.
                # The interval is [L_int, R_int]
                L_int = N * Q
                R_int = N * (Q + 1) - 1
                # We only need to check if there is any M in [L_int, R_int] with no zeros.
                # If the interval is large, it's more likely.
                # For small intervals, we can just check.
                if R_int - L_int < 1000:
                    for M in range(L_int, R_int + 1):
                        if L == len(str(M)) and has_no_zeros(M):
                            max_a = max(max_a, count_zeros(Q))
                            break
                else:
                    # For larger intervals, it's almost certain.
                    # But let's be careful.
                    max_a = max(max_a, count_zeros(Q))
    return max_a

for L in range(1, 11):
    print(f"L={L}, max_a={check_max_a(L)}")
